import{_ as l,c as i,o as a,ag as o}from"./chunks/framework.DJBJE7_Z.js";const b=JSON.parse('{"title":"Web 端更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"overview/changelog/web.md","filePath":"overview/changelog/web.md"}'),t={name:"overview/changelog/web.md"};function r(d,e,n,c,s,h){return a(),i("div",null,e[0]||(e[0]=[o('<h1 id="web-端更新日志" tabindex="-1">Web 端更新日志 <a class="header-anchor" href="#web-端更新日志" aria-label="Permalink to &quot;Web 端更新日志&quot;">​</a></h1><h2 id="v1-3-0-2026-06-09" tabindex="-1">v1.3.0 (2026-06-09) <a class="header-anchor" href="#v1-3-0-2026-06-09" aria-label="Permalink to &quot;v1.3.0 (2026-06-09)&quot;">​</a></h2><ul><li><code>@netless/forge-room</code>、<code>@netless/forge-whiteboard</code>、<code>@netless/forge-imagery-doc</code>、<code>@netless/forge-slide</code> 正式发布 <code>1.3.0</code>。</li><li>稳定支持 pageId 页面管理能力：<code>addPage</code>、<code>gotoPage</code>、<code>deletePage</code>、<code>pageList</code>、<code>currentPageId</code>。</li><li><code>Whiteboard.insertImage</code> 支持 <code>pageId</code>、<code>fit</code>、<code>role</code> options，可用于指定插入页面、适配方式和背景图角色。</li><li>IndexedNavigation bridge handler 对齐 <code>whiteboard.indexed*</code> 命名，提升 Web / JSBridge / Native 跨端一致性。</li><li>对齐 snapshot 上传策略：基于当前 live docs 全量构建 snapshot，避免上传内容长期停留在历史状态。</li><li>提升 join 阶段同步稳定性：subdoc 远端更新在 <code>@room/subDocs</code> 未就绪时先缓存后重放，减少 join 中同步消息漏处理的问题。</li></ul><h2 id="v1-3-0-beta-1-2026-05-19" tabindex="-1">v1.3.0-beta.1 (2026-05-19) <a class="header-anchor" href="#v1-3-0-beta-1-2026-05-19" aria-label="Permalink to &quot;v1.3.0-beta.1 (2026-05-19)&quot;">​</a></h2><ul><li><code>Whiteboard.insertImage</code> 支持 <code>fit</code> 配置，可用于控制插入图片的适配方式。</li><li>优化白板背景图与 IndexedNavigation 页面导航处理，提升背景图和翻页场景的稳定性。</li><li>优化 ReplayPlayer 时间线与白板渲染处理。</li><li>修复绘制曲线过程中清空页面可能导致异常或残留的问题。</li><li>补充背景图与 IndexedNavigation 相关测试覆盖。</li></ul><h2 id="v1-2-1-2026-05-27" tabindex="-1">v1.2.1 (2026-05-27) <a class="header-anchor" href="#v1-2-1-2026-05-27" aria-label="Permalink to &quot;v1.2.1 (2026-05-27)&quot;">​</a></h2><ul><li>修复 room 初始化向量同步稳定性问题，降低多人加入或恢复时的数据同步异常风险。</li><li>延续 <code>1.3.0-beta.1</code> 中的白板背景、页面导航、插图适配和清空绘制中曲线相关修复。</li></ul><h2 id="v1-2-0-2026-05-26" tabindex="-1">v1.2.0 (2026-05-26) <a class="header-anchor" href="#v1-2-0-2026-05-26" aria-label="Permalink to &quot;v1.2.0 (2026-05-26)&quot;">​</a></h2><ul><li>加强入房与快照恢复稳定性：<code>joinRoom</code> 区分 404 / 5xx 场景，404 自动走 <code>fullRoomExchange</code> 兜底，避免重复 <code>initVector</code> 交换。</li><li>优化数据交换策略：优先从 writable peers 同步，限制 peer 数与超时时间，降低大房间同步抖动。</li><li>writable 切换为 readonly 时立即强制上传快照，减少只读用户恢复不完整的情况。</li><li><code>conflictV2</code> 支持 <code>forge-room-doc</code> 主文档，冲突恢复覆盖更完整。</li><li>重构 Metrics/WhiteTracker 上报链路，统一按 60 秒聚合上报 <code>sendRate</code>、<code>conflict</code>、<code>fps</code>、<code>snapshot</code> 等指标。</li><li>指标增强：补充 Snapshot 成功率与平均耗时，FPS 增加 P90 百分位，且 dev/private 区域不再上报。</li><li>新增 <code>ReplayPlayer</code> 虚拟时钟回放能力，并补强 window manager 初始化与回放时序。</li><li>修复 Apple Pencil 手掌误触导致笔迹中断的问题。</li><li>优化曲线笔迹质量与缩放场景下的书写一致性，减少缩放后笔迹表现失真。</li><li>插入图片时自动按当前视口居中并按比例适配展示。</li><li>点文本初始化流程优化，避免首次创建时 points 重复设置。</li><li>图片渲染与截图流程增加跨域处理和错误兜底，提升导出稳定性。</li><li>修复 logger 生命周期重复创建/释放问题，释放 <code>Room</code> 实例计数，提升多次进出房间稳定性。</li><li>新增并完善 snapshot strategy、conflict-room-doc、metrics 等 Playwright/E2E 测试覆盖。</li></ul><h2 id="v1-2-0-beta-3-2026-05-11" tabindex="-1">v1.2.0-beta.3 (2026-05-11) <a class="header-anchor" href="#v1-2-0-beta-3-2026-05-11" aria-label="Permalink to &quot;v1.2.0-beta.3 (2026-05-11)&quot;">​</a></h2><ul><li>移除曲线压感点异常影响，提升白板曲线绘制稳定性。</li><li>优化文本点初始化逻辑，避免 point text 初始化时重复设置 points。</li><li>作为 JSBridge / Native 同步基线，供 Android 与 iOS 内嵌资源对齐。</li></ul><h2 id="v1-1-2-2026-04-01" tabindex="-1">v1.1.2 (2026-04-01) <a class="header-anchor" href="#v1-1-2-2026-04-01" aria-label="Permalink to &quot;v1.1.2 (2026-04-01)&quot;">​</a></h2><h3 id="指标上报重构" tabindex="-1">指标上报重构 <a class="header-anchor" href="#指标上报重构" aria-label="Permalink to &quot;指标上报重构&quot;">​</a></h3><ul><li>所有质量指标改为通过 WhiteTracker 上报（替代 log），POST 到统一的指标收集端点</li><li>所有周期性指标统一为每 60 秒聚合上报一次，大幅减少日志量 <ul><li>消息发送速率（sendRate）：1s → 60s</li><li>冲突次数 / 解决耗时（conflict）：事件驱动 → 60s 聚合</li><li>FPS：~5s → ~60s，新增 P90 百分位</li><li>Snapshot 上传：每次即时上报 → 60s 聚合，包含成功率和平均耗时</li></ul></li><li>WhiteTracker 去除 white-sdk 依赖（createWhiteBasicTags），OS 从 userAgent 提取</li><li>WhiteTracker 删除内置 FPS 统计，统一由白板渲染层上报</li><li>dev / private region 不上报指标数据</li></ul><h3 id="joinroom-稳定性改进" tabindex="-1">joinRoom 稳定性改进 <a class="header-anchor" href="#joinroom-稳定性改进" aria-label="Permalink to &quot;joinRoom 稳定性改进&quot;">​</a></h3><ul><li>Snapshot 服务端 5xx 错误时直接抛出 SNAPSHOT_SERVER_ERROR，不再静默失败</li><li>Snapshot 404 时自动走 fullRoomExchange 兜底，从在线用户同步数据 <ul><li>writable 用户优先选择，最多 10 peers，3000ms 超时</li><li>兜底完成后跳过 Step 8 initVector，避免重复数据交换</li></ul></li><li>writable → readonly 切换时立即 force putSnapshot，防止数据丢失</li><li>conflictV2 支持 forge-room-doc，room 主文档也能参与冲突响应</li></ul><h3 id="白板体验优化" tabindex="-1">白板体验优化 <a class="header-anchor" href="#白板体验优化" aria-label="Permalink to &quot;白板体验优化&quot;">​</a></h3><ul><li>修复 Apple Pencil 手掌误触导致笔迹中断的问题</li><li>优化曲线笔迹质量，支持真实 Apple Pencil 压感</li><li>缩放感知的 perfect-freehand 参数，笔迹粗细跟随 zoom 变化</li><li>WhiteboardTool 基类增加拖拽事件节流，减少高频事件开销</li></ul><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><ul><li>新增 ReplayPlayer 虚拟时钟回放功能</li><li>新增 joinRoom 分阶段计时，各步骤耗时随日志上报</li><li>新增 Metrics 指标统计类（gauge / count / start 语义）</li><li>新增 playwright e2e 测试覆盖 snapshot strategy、conflict-room-doc、metrics 上报</li></ul><h2 id="v1-1-1-2026-01-28" tabindex="-1">v1.1.1 (2026-01-28) <a class="header-anchor" href="#v1-1-1-2026-01-28" aria-label="Permalink to &quot;v1.1.1 (2026-01-28)&quot;">​</a></h2><ul><li>提供 <code>Whiteboard.setPerformanceMode</code> 动态设置性能模式</li></ul><h2 id="v1-1-0-2025-12-24" tabindex="-1">v1.1.0 (2025-12-24) <a class="header-anchor" href="#v1-1-0-2025-12-24" aria-label="Permalink to &quot;v1.1.0 (2025-12-24)&quot;">​</a></h2><ul><li>仅发版操作, 无更新</li></ul><h2 id="v1-1-0-beta-4-2025-12-22" tabindex="-1">v1.1.0-beta.4 (2025-12-22) <a class="header-anchor" href="#v1-1-0-beta-4-2025-12-22" aria-label="Permalink to &quot;v1.1.0-beta.4 (2025-12-22)&quot;">​</a></h2><p>🐛 问题修复</p><ul><li>修复白板元素层级显示错误的问题</li></ul><p>🔧 其他</p><ul><li>清理调试代码</li></ul><h2 id="_1-1-0-beta-3-2025年12月11日" tabindex="-1">1.1.0-beta.3 - 2025年12月11日 <a class="header-anchor" href="#_1-1-0-beta-3-2025年12月11日" aria-label="Permalink to &quot;1.1.0-beta.3 - 2025年12月11日&quot;">​</a></h2><p><strong>@netless/forge-room</strong></p><ul><li>新增房间级别只读,可写权限</li><li>joinRoom 方法新增 timeout 参数, 手动指定超时时间</li><li>修复部分情况下 yjs 同步异常的问题</li></ul><p><strong>@netless/forge-whiteboard@1.0.0</strong>:</p><ul><li>修复白板画笔未销毁导致的内存泄漏问题</li><li>修复 yjs 更新顺序不确定导致插入图片失败的问题</li></ul><h2 id="v1-1-0-beta-2-2025-12-05" tabindex="-1">v1.1.0-beta.2 (2025-12-05) <a class="header-anchor" href="#v1-1-0-beta-2-2025-12-05" aria-label="Permalink to &quot;v1.1.0-beta.2 (2025-12-05)&quot;">​</a></h2><p>🐛 问题修复</p><ul><li>修复幻灯片冻结功能</li><li>修复在线用户数量统计不准确的问题</li><li>添加文档缺失的日志记录，方便排查问题</li><li>修复内存泄漏问题</li><li>修复空日志输出</li><li>修复幻灯片与白板模式同步问</li></ul><h2 id="v1-1-0-beta-1-2025-11-25" tabindex="-1">v1.1.0-beta.1 (2025-11-25) <a class="header-anchor" href="#v1-1-0-beta-1-2025-11-25" aria-label="Permalink to &quot;v1.1.0-beta.1 (2025-11-25)&quot;">​</a></h2><p>✨ 新功能</p><ul><li>完整的权限管理系统：实现用户可写/只读权限控制</li><li>权限通知机制：权限变更时自动通知</li><li>移动端支持：添加触摸手势操作</li><li>端到端测试：完善测试覆盖</li></ul><p>🐛 问题修复</p><ul><li>修复白板图片源更新不显示的问题</li><li>修复只读用户可以执行撤销/重做的问题</li><li>修复只读用户可以清空白板页面的问题</li><li>修复只读用户可以添加白板页面的问题</li><li>修复只读用户可以同步页面的问题</li><li>修复只读用户可以启动子应用的问题</li><li>修复 PDF 和 socketio-provider 构建错误</li><li>修复 ydoc 客户端 ID 问题</li></ul><h2 id="v1-0-9-2025-11-25" tabindex="-1">v1.0.9 (2025-11-25) <a class="header-anchor" href="#v1-0-9-2025-11-25" aria-label="Permalink to &quot;v1.0.9 (2025-11-25)&quot;">​</a></h2><p>🐛 问题修复</p><ul><li>修复日志获取错误</li></ul><h2 id="v1-0-8-2025-11-25" tabindex="-1">v1.0.8 (2025-11-25) <a class="header-anchor" href="#v1-0-8-2025-11-25" aria-label="Permalink to &quot;v1.0.8 (2025-11-25)&quot;">​</a></h2><p>🐛 问题修复</p><ul><li>移除重复的日志输</li></ul><h2 id="v1-0-7-2025-09-10" tabindex="-1">v1.0.7 (2025-09-10) <a class="header-anchor" href="#v1-0-7-2025-09-10" aria-label="Permalink to &quot;v1.0.7 (2025-09-10)&quot;">​</a></h2><p>✨ 新功能</p><ul><li>媒体播放器添加静音设置 API</li><li>统一日志上传流程和格式</li><li>支持区域参数</li><li>支持历史消息查询方法</li></ul><p>🐛 问题修复</p><ul><li>更新 socketIOProvider 的历史消息处理</li><li>修复日志调度问题</li><li>修复 PPT 多次刷新后白屏的问题</li><li>优化冲突处理逻辑</li><li>修复历史消息解码错误</li></ul><h2 id="_1-0-0-2025年7月24日" tabindex="-1">1.0.0 - 2025年7月24日 <a class="header-anchor" href="#_1-0-0-2025年7月24日" aria-label="Permalink to &quot;1.0.0 - 2025年7月24日&quot;">​</a></h2><p><strong>更新</strong></p><ul><li><strong>@netless/forge-room@1.0.0</strong>: 房间管理系统 v1.0.0 发布，提供应用生命周期管理、用户管理、权限控制、数据备份恢复及回放功能。</li><li><strong>@netless/forge-imagery-doc@1.0.0</strong>: 图像文档处理系统 v1.0.0 发布，支持图片文档的查看和协作标注。</li><li><strong>@netless/forge-slide@1.0.0</strong>: 幻灯片展示模块 v1.0.0 发布，集成了幻灯片展示功能。</li><li><strong>@netless/forge-rtm@1.0.0</strong>: 实时消息传输模块 v1.0.0 发布，支持 RTM（Real-Time Messaging）信令通道。</li><li><strong>@netless/forge-whiteboard@1.0.0</strong>: 实时白板模块 v1.0.0 发布，包含丰富的绘制工具、专业工具、样式配置、多页面管理、细粒度权限控制和实时相机控制。</li></ul>',56)]))}const v=l(t,[["render",r]]);export{b as __pageData,v as default};
